	title 'PictureDefProc'************************************************************************ Picture Control Def Proc*** Copyright (C)* Apple Computer, Inc.  1986-1989* All Rights Reserved** 23 Sep 88	Steven Glass** Coding begin from modified version of the statText custom control* which came from Tech Support's custom control (by Keith Rollin).** 06 NOv 88	Steven Glass** Allow for default rect calculation in do_init.** 28 mar 89	Steven Glass** Changed init routine to use standard descriptors for Picture Ref.** Added support for CtlWinStateChange message.  This defProc ignores* it since pictures look the same in inactive and active windows.** 15 May 89	Steven Glass** Changed jsr to LoadResource to _CMLoadResource so can segment this* proc.** Released the resource when control is killed!!!!** 17-Sep-90	Dave Lyons** Removed dependency on all.macros.***********************************************************************	blanks off	string asis	print push	print off***	include 'all.macros'	;removed 17-Sep-90 DAL	include 'm16.util2'	include 'm16.memory'	include 'm16.quickdraw'	include 'm16.qdaux'	include 'm16.control'	include 'm16.window'	include 'm16.resources'	include 'CtlCustomEqus.asm'	include 'e16.quickdraw'	include 'e16.font'	include 'e16.resources'	print pop;-----------------------------------------------------------;; Stack Fram Equates for control;	DefineStackOrigD	WORD	; caller's saved direct page registerOrigB	byte	; caller's saved data bank registerCtlPtr	LONG	; pointer to control recordRtnAddr	block 3	; RTL address back to Control ManagertheCtlHandle	LONG	; handle to control recordCtlParam	LONG	; add'l parameter passed to DefProcCtlCode	WORD	; operation to performReturnValue	LONG	; space for return value to Ctl Mgr.	title 'PictureDefProc -- MainEntry'*****************************************************************PicProc	PROC EXPORT** This is the def_proc for picture controls.  When this* routine gets control, the stack looks as described below.**** Inputs:	On entry, the parameters are passed to us on the stack.**	|	| Previous Contents*	|-------------------|*	|    ReturnValue	| LONG - Space for return value*	|-------------------|*	|    CtlCode	| WORD - operation to perform*	|-------------------|*	|    CtlParam	| LONG - add'l parameter*	|-------------------|*	|    theCtlHandle	| LONG - Handle to control record*	|-------------------|*	|    RtnAddr	| 3 BYTES - RTL address*	|-------------------|*	|	| <-- Stack pointer** Outputs:	Put something into ReturnValue, pull off the parameters,*	and return to the Control Manager.**	|	| Previous Contents*	|-------------------|*	|    ReturnValue	| LONG - Space for return value*	|-------------------|*	|    RtnAddr	| 3 BYTES - RTL address*	|-------------------|*	|	| <-- Stack pointer** External Refs:	import do_draw	import do_nothing	import do_test	import do_init	import do_dispose	import do_recsize** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	pha	; push on some room	for 'CtlPtr'	pha	phb	; save the Data Bank register	phd	; save the Direct Page register	phk	; switch data bank to program bank	plb	tsc	; switch Direct Page into stack	tcd	lda <CtlCode	cmp #recSize	beq SkipDeref	lda [<theCtlHandle]	sta <CtlPtr	ldy #2	lda [<theCtlHandle],y	sta <CtlPtr+2SkipDeref	lda <CtlCode		; get routine # to call	cmp #ctlWinStateChange+1	; make sure msg is in range 	blt ShiftIt	lda #6		; force unknown codes to null eventsShiftIt	asl a	tax	jsr (ActionTable,x)	sta <ReturnValue		; save the return value	stx <ReturnValue+2;; The Return Value has been stored on the stack, and it is time for us to; return back to the Control Manager. Before we do so, however, we must; remove the parameters that were passed to us on the stack. We do this; by moving the RTL address up just below the Return Value, getting the; stack pointer, and adding an amount to it so that we point to where; the RTL address has been moved to. We can then simply RTL back to the; Control Manager, and it will pick up the Return Value right off of the; stack!;	lda <RtnAddr	; move the return address up	sta <ReturnValue-3	lda <RtnAddr+1	sta <ReturnValue-2	tsc	; Get the stack pointer	pld	; restore caller's Data Bank and	plb	; Direct Page registers	clc	; Adjust the stack pointer to point to	adc #ReturnValue-4	; the new location of the RTL address.	tcs	; Put the stack pointer back.	rtl	; back to the caller;ActionTable	DC.W do_draw	0 Draw simple button.	DC.W do_nothing	1 Compute drag RECT.	DC.W do_test	2 Common hit test routine.	DC.W do_init	3 Initialize the control.	DC.W do_dispose	4 Dispose.	DC.W do_draw	5 New value.	DC.W do_nothing	6 Compute Thumber constrains.	DC.W do_nothing	7 Drag the indicator.	DC.W do_nothing	8 Auto action.	DC.W do_draw	9 New value.	DC.W do_nothing	10 Set min max.	DC.W do_nothing	11 Move button.	DC.W do_recsize	12 Return size of standard record.	dc.W do_nothing	13 take key or menu event	dc.W do_nothing	14 ctlChangeTarget	dc.W do_nothing	15 ctlChagneBounds	dc.W do_nothing	16 ctlWindChagneSize	dc.W do_nothing	17 ctlHandleTab	dc.W do_nothing	18 ctlNotifyMultiPart	dc.W do_nothing	19 ctlWinStateChange (Pic Ctls do not redraw)	ENDP	title 'PictureDefProc -- do_recsize'*****************************************************************do_recsize	PROC** Returns the size of the control record.*** Inputs:*	none** Outputs:*	a-reg & x-reg hold result for def proc** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #superCtlSize	ldx #0		High word of size.		rts		ENDP	title 'PictureDefProc -- Do_Nothing'*****************************************************************do_nothing	PROC** This is the routine we use when there is nothing to do.* It just returns zeros in the a and x registers.*** Inputs:*	ctlHandle*	ctlPtr** Outputs:*	a-reg & x-reg hold result for def proc** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;	lda #0	Nothing flag.	tax		rts		ENDP	title 'PictureDefProc -- Do_Init'*****************************************************************do_init	PROC** Inits fields in the control record based on the values in* in the control template.** The ctlData field is set to be a pointer to the static text* and the ctlValue field is set to be the size of the static* text field (from the value in the template).*** Inputs:*	ctlHandle*	ctlPtr*	ctlParam = ptr to template** Outputs:*	a-reg and x-reg are zero.** External Refs:	import PushCtlData	import ConvertToHandle** Entry Points:*	none*	longa on	; mode	longi on** Change History** 06 Nov 88	Steven Glass** If the control rect is has 0 for bottom, we calculate* the rect using the frame rect in the picture.  This will give* us a rect that has no scaling.*****************************************************************	ldy #PictureTemplate.PicRef+2	lda [<ctlParam],y	tax	dey	dey	lda [<ctlParam],y	ldy #NewCtlRecord.ctlData	sta [<ctlPtr],y	iny	iny	txa	sta [<ctlPtr],y	ldy #NewCtlRecord.ctlRect+4	lda [ctlPtr],y	bne RectIsComplete	pha		; space for result	pha	jsr PushCtlData		; push ref on stack	jsr ConvertToHandle		; turn ref into handle (if not already)	pla		; deref the picture handle in ctlParam	sta ctlParam	pla	sta ctlParam+2	lda [ctlParam]	tax	ldy #2	lda [ctlParam],y	sta ctlParam+2	stx ctlParam	ldy #6		; height of frame rect is bottom-top	lda [ctlParam],y	sec	ldy #2	sbc [ctlParam],y	clc	ldy #NewCtlRecord.ctlRect	; add to control rect top	adc [ctlPtr],y	ldy #NewCtlRecord.ctlRect+4	sta [ctlPtr],y	ldy #8		; width of frame rect is left-right	lda [ctlParam],y	sec	ldy #4	sbc [ctlParam],y	clc	ldy #NewCtlRecord.ctlRect+2	; add to control rect left to get right	adc [ctlPtr],y	ldy #NewCtlRecord.ctlRect+6	sta [ctlPtr],yRectIsComplete	lda #0	tax	rts	ENDP	title 'PictureDefProc -- Do_Dispose'*****************************************************************do_Dispose	PROC EXPORT** Inits fields in the control record based on the values in* in the control template.** The ctlData field is set to be a pointer to the static text* and the ctlValue field is set to be the size of the static* text field (from the value in the template).*** Inputs:*	ctlHandle*	ctlPtr*	ctlParam = ptr to template** Outputs:*	a-reg and x-reg are zero.** External Refs:	import PushCtlData** Entry Points:*	none*	longa on	; mode	longi on** Change History** 15 May 89	Steven Glass** Added.*****************************************************************	ldy #NewCtlRecord.ctlMoreFlags	lda [ctlPtr],y	and #$0003		; only care about low 2 bits	cmp #1	;(RefIsHandle)	; If not handle, it must be resource	beq JustAHandle	PushWord #rPicture	jsr PushCtlData	_CMReleaseResourceJustAHandle	lda #0	tax	rts	ENDP	title 'PictureDefProc -- do_test'*****************************************************************do_test	PROC** Test if the mouse is down in the control.  We always* return no, since it does not make sense to "click" on* static text.*** Inputs:*	ctlParam = point to check*** Outputs:*	a-reg and x-reg are always zero** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #0	Never return a part code	tax		rts		ENDP	title 'PictureDefProc -- Do_Draw'*****************************************************************do_draw	PROC** Draws the control using DrawPicture.*** Inputs:*	ctlHandle*	ctlPtr** Outputs:*	a-reg and x-reg are zero.** External Refs:*	none** Entry Points:	ENTRY PushCtlData	ENTRY ConvertToHandle*	longa on	; mode	longi on** Change History** 28 Mar 89	Steven Glass** Changed definitions of moreFlags bits so that low two bits* are used like all other controls: 0 = ptr, 1 = handle, 2 =* resource.** Docs will state that 0 is invalid.*****************************************************************	pha		; space for result	pha	jsr PushCtlData		; push ref on stack	jsr ConvertToHandle		; turn ref into handle (if not already)	lda ctlPtr		; point to control rect	clc	adc #NewCtlRecord.ctlRect	tax	lda ctlPtr+2	adc #0	pha	phx	_DrawPicture	lda #0	tax	rtsPushCtlData	plx	ldy #NewCtlRecord.ctlData+2	lda [ctlPtr],y	pha	dey	dey	lda [ctlPtr],y	pha	phx	rts;-----------------------------------------------------------;; Looks at the more flags to see what the data value holds.; The low 2 bits of the flag indicate:;;     0  undefined;     1  handle;     2  resource;ConvertToHandle	ldy #NewCtlRecord.ctlMoreFlags	lda [ctlPtr],y	and #$0003		; only care about low 2 bits	cmp #1	;(RefIsHandle)	; If not handle, it must be resource	beq AlreadyHandle	lda 3,s	tax	lda 5,s	pha	pha	PushWord #rPicture	pha	phx	_CMLoadResource	pla	ply	plx	sta 5,s	tya	sta 7,s	pla	pla	phx	rts	AlreadyHandle	plx	lda 1,s	sta 5,s	lda 3,s	sta 7,s	pla	pla	phx	clc	rts		ENDP	END